-- SAT MASTER · 0011 · Storage buckets (private). Students receive short-lived signed URLs
-- generated by the server after authorization; no public bucket and no student read policy.
-- Guarded so the migration is a no-op where the storage schema is absent (local test harness).

do $outer$
begin
  if not exists (select 1 from information_schema.schemata where schema_name = 'storage') then
    raise notice 'storage schema not present — skipping bucket setup';
    return;
  end if;

  insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types) values
    ('question-images', 'question-images', false, 2097152, array['image/png','image/jpeg','image/webp','image/svg+xml']),
    ('lesson-resources', 'lesson-resources', false, 20971520, array['application/pdf','image/png','image/jpeg']),
    ('lesson-videos', 'lesson-videos', false, 524288000, array['video/mp4','video/webm'])
  on conflict (id) do nothing;

  execute $p$
    create policy "staff upload content media" on storage.objects for insert to authenticated
      with check (bucket_id in ('question-images','lesson-resources','lesson-videos') and (select public.is_content_manager()))
  $p$;
  execute $p$
    create policy "staff read content media" on storage.objects for select to authenticated
      using (bucket_id in ('question-images','lesson-resources','lesson-videos') and (select public.is_staff()))
  $p$;
  execute $p$
    create policy "staff update content media" on storage.objects for update to authenticated
      using (bucket_id in ('question-images','lesson-resources','lesson-videos') and (select public.is_content_manager()))
  $p$;
  execute $p$
    create policy "staff delete content media" on storage.objects for delete to authenticated
      using (bucket_id in ('question-images','lesson-resources','lesson-videos') and (select public.is_content_manager()))
  $p$;
end
$outer$;
